module benchmark/solution

type State = Idle | HasCredit(int) | Dispensing(int)

type Event = Insert(int) | Select(int) | DispenseDone

pure func price(code: int) -> Option[int] =
  match code {
    1 => Some(125),
    2 => Some(75),
    3 => Some(100),
    _ => None
  }

pure func step(state: State, event: Event) -> Result[State, string] =
  match (state, event) {
    (Idle, Insert(n)) => Ok(HasCredit(n)),
    (Idle, Select(_)) => Err("no_credit"),
    (Idle, DispenseDone) => Err("not_dispensing"),
    (HasCredit(c), Insert(n)) => Ok(HasCredit(c + n)),
    (HasCredit(c), Select(code)) => match price(code) {
      None => Err("unknown_item"),
      Some(p) => if c < p then Err("insufficient_funds") else Ok(Dispensing(c - p))
    },
    (HasCredit(_), DispenseDone) => Err("not_dispensing"),
    (Dispensing(_), Insert(_)) => Err("busy"),
    (Dispensing(_), Select(_)) => Err("busy"),
    (Dispensing(_), DispenseDone) => Ok(Idle)
  }

pure func showState(s: State) -> string =
  match s {
    Idle => "IDLE",
    HasCredit(n) => "CREDIT(${show(n)})",
    Dispensing(ch) => "DISPENSING(${show(ch)})"
  }

func run(state: State, events: [Event]) -> () ! {IO} =
  match events {
    [] => (),
    e :: rest => match step(state, e) {
      Ok(s) => {
        println("ok: ${showState(s)}");
        run(s, rest)
      },
      Err(reason) => {
        println("err: ${reason}");
        run(state, rest)
      }
    }
  }

export func main() -> () ! {IO} =
  run(Idle, [Insert(50), Select(1), Insert(100), Select(1), Insert(50), DispenseDone, Select(2), Insert(100), Select(2), DispenseDone])

